const article = $('Code').first().json;

const icps = $('ICP_Segments').all().map(i => i.json);
const lifecycleStages = $('Lifecycle_Stages').all().map(i => i.json);
const strategicPriorities = $('Strategic_Priorities').all().map(i => i.json);

return [{
  json: {
    article,
    icps,
    lifecycleStages,
    strategicPriorities
  }
}];

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const html = data['content:encoded'] || '';

  const content = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    json: {
      title: data.title,
      url: data.link,
      publishedAt: data.pubDate,
      author: data.creator,
      content: content
    }
  };
});

const response = $input.first().json;

const text = response.content.parts
  .map(part => part.text || '')
  .join('')
  .replace(/```json|```/g, '')
  .trim();

const classification = JSON.parse(text);

const scores = [
  classification.primary_icp?.confidence,
  classification.primary_lifecycle?.confidence,
  ...(classification.strategic_alignment || [])
    .map(item => item.confidence)
].filter(score => typeof score === 'number');

const lowConfidence = scores.some(score => score < 0.75);

classification.human_review_required =
  lowConfidence ||
  !classification.primary_icp?.id ||
  !classification.primary_lifecycle?.id;

return [{
  json: {
    article: $('Prepare AI Classification Input').first().json.article,
    classification,
    human_review_required: classification.human_review_required,
    strategic_alignment_status: 'hypothetical'
  }
}];

const previous = $('Parse Classification').first().json;

const founders = $('Founder_Voices')
  .all()
  .map(item => item.json);

if (founders.length !== 2) {
  throw new Error('Expected exactly two founder profiles');
}

return [{
  json: {
    article: previous.article,
    classification: previous.classification,
    founders,
    generation_rules: {
      posts_per_founder: 3,
      total_posts: 6,
      require_human_approval: true,
      prohibit_invented_claims: true,
      prohibit_invented_experiences: true
    }
  }
}];

const response = $input.first().json;

const text = response.content.parts
  .map(part => part.text || '')
  .join('')
  .replace(/```json|```/g, '')
  .trim();

const review = JSON.parse(text);

if (!Array.isArray(review.posts) || review.posts.length !== 6) {
  throw new Error('Expected exactly 6 reviewed posts');
}

const article = $('Prepare LinkedIn Generation Input')
  .first().json.article;

return review.posts.map(post => ({
  json: {
    founder_id: post.founder_id,
    day: post.day,
    editorial_status: post.editorial_status,
    editorial_issues: post.issues,
    suggested_revisions: post.suggested_revisions,
    draft_text: post.revised_post_text,
    source_url: article.url,
    article_title: article.title,
    approval_status: 'Pending',
    human_approval_required: true
  }
}));
